package com.gymmind.nutrition.infrastructure.persistence; import com.gymmind.nutrition.domain.model.NutritionFood; import com.gymmind.nutrition.domain.repository.NutritionFoodRepository; import org.springframework.stereotype.Repository; @Repository class JpaNutritionFoodRepository implements NutritionFoodRepository { final SpringDataNutritionFoodRepository d; JpaNutritionFoodRepository(SpringDataNutritionFoodRepository d){this.d=d;} public NutritionFood save(NutritionFood f){return d.save(f);} }
